package android.util; public class SparseArray<E> {private final java.util.TreeMap<Integer,E> m=new java.util.TreeMap<>();public void append(int k,E v){m.put(k,v);}public E get(int k){return m.get(k);}public void remove(int k){m.remove(k);}public void clear(){m.clear();}public int size(){return m.size();}public E valueAt(int i){return new java.util.ArrayList<E>(m.values()).get(i);}}
